  "Inventory structures": "Estruturas de inventário",
  "Use Setup & builders to create a separate inventory structure/list. Verification and custody history are not imported.": "Use Configuração e editores para criar uma estrutura/lista de inventário separada. O histórico de conferência e custódia não é importado.",
  "Toolbox forms": "Formulários de diálogos de segurança",
  "Use Setup & builders to create a new unpublished toolbox-talk form. Meetings and acknowledgements are not imported.": "Use Configuração e editores para criar um novo formulário não publicado de diálogo de segurança. Reuniões e confirmações de leitura não são importadas.",
  "Logbook definitions": "Definições de livros de registro",
  "Use Setup & builders for a clean definitions-only logbook. Saved entries, corrections, media and history are deliberately omitted.": "Use Configuração e editores para criar um livro de registro limpo, apenas com as definições. Registros salvos, correções, mídias e histórico são excluídos deliberadamente.",
  "Documents and worksheets": "Documentos e planilhas",
  "PDF / DOCX / Excel / text / scans": "PDF / DOCX / Excel / texto / digitalizações",
  "PDF, DOCX, XLSX, XLSM, CSV, TXT and scans can become editable definitions or separate inventory lists in Setup & builders. Select and review each worksheet; formulas, macros and links never run.": "PDF, DOCX, XLSX, XLSM, CSV, TXT e digitalizações podem se tornar definições editáveis ou listas de inventário separadas em Configuração e editores. Selecione e revise cada aba; fórmulas, macros e links nunca são executados.",
  "Complete company workspace / reusable setup": "Área de trabalho completa da empresa / configuração reutilizável",
  "Advanced/native transfer only. A full company-workspace transfer belongs in a separate company workspace; never overwrite operational data.": "Somente transferência avançada/nativa. A transferência completa da área de trabalho de uma empresa deve ser feita em uma área separada; nunca sobrescreva dados operacionais.",
  "Original reference file": "Arquivo original de referência",
  "PDF / Office / image": "PDF / Office / imagem",
  "Use Original files in the browser. Uploading a source document does not automatically create a checklist, certificate or Task.": "Use Arquivos originais no navegador. Enviar um documento-fonte não cria automaticamente uma lista de verificação, certificado ou tarefa.",
