  "Dates describe the supplied record, not certificate authenticity or equipment readiness. Draft records are visible to permitted certificate viewers. Unknown expiry is not a no-expiry declaration.": "As datas descrevem o registro fornecido; não comprovam a autenticidade do certificado nem a prontidão do equipamento. Rascunhos são visíveis a quem tem permissão de visualizar certificados. Validade desconhecida não significa validade indeterminada.",
