  "Recording maintenance and its review is not a return-to-service authorisation. Local saved forms are not server-confirmed evidence.": "O registro e a revisão da manutenção não autorizam o retorno ao serviço. Formulários locais ainda não são evidências confirmadas pelo servidor.",
  "Recorded as": "Registrado por",
  "Save needs a hub connection; a local draft is not a submitted action.": "É necessário estar conectado ao servidor para enviar. Um rascunho local ainda não foi enviado.",
  "Last saved result": "Último resultado salvo",
