  "Work in progress. Save the readings and notes recorded so far.": "Trabalho em andamento. Salve as leituras e observações já registradas.",
  "Work notes; explain N/A or issues": "Observações do trabalho; justifique problemas ou situações não aplicáveis",
  "Your account, time and before/after result are recorded automatically. Saving does not approve the work or close the order.": "Sua conta, o horário e os resultados anterior e atual são registrados automaticamente. Salvar não aprova o trabalho nem encerra a ordem.",
