  "ADMINISTRATION /": "ADMINISTRAÇÃO /",
  "{0} saved accounts": "{0} contas salvas",
  "{0} saved departments": "{0} departamentos salvos",
  "HSE / QSHE": "Segurança e qualidade",
  "project user": "Usuário da empresa",
  "vessel only": "Acesso restrito à embarcação",
  "An administrator has full company-workspace access. Security roles are not vessel-specific; Fleet access is managed separately. These changes sign the edited user out.": "O administrador tem acesso completo ao ambiente da empresa. A função de segurança não define acesso a embarcações específicas; esse acesso é configurado na área de Frota. Ao salvar estas alterações, as sessões dessa conta serão encerradas.",
  "Account and permission changes revoke that person's saved sessions. Existing work, identities and evidence remain. Use the account menu to change your own password.": "Alterações na conta ou nas permissões encerram as sessões dessa pessoa. Seus registros, identificadores e evidências são preservados. Para alterar sua própria senha, use o menu da conta.",
  "These are the independent administrator-owned permission flags. Delegated grants are listed separately in Invitations & access and are never silently converted into independent rights by this form. Saved permission flags do not replace record ownership, assignments or approval rules. Full backups are unencrypted and are not filtered by recipient.": "Estas permissões são concedidas diretamente pelo administrador. Os acessos delegados aparecem separadamente em Convites e acesso e não são convertidos por este formulário. As regras de autoria, atribuição de responsáveis e aprovação continuam valendo. O backup completo contém o banco inteiro, sem criptografia e sem filtro por destinatário.",
  "Own records and submission rights are personal. Document, travel, crew assignment and review rights cover the company and require separate administrator grants. Personal certificates and passports stay separate from Inventory certificates. Reviewers cannot approve their own submissions.": "Cada colaborador consulta e envia seus próprios registros. As permissões de gestão de documentos, viagens, escalas e análise de solicitações abrangem a empresa e precisam ser concedidas pelo administrador. Documentos pessoais, como certificados e passaportes, ficam separados dos certificados de equipamentos no Inventário. Ninguém pode aprovar a própria solicitação.",
  "Company access actions also require an explicit department scope and grant allowance. Use Invitations & access → Delegation to configure both together. No onward delegation or automatic approval is granted by a checkbox.": "O acesso à empresa também depende dos departamentos autorizados e dos limites de concessão. Configure ambos em Convites e acesso → Delegação. Marcar uma opção não permite repassar a delegação nem aprovar solicitações automaticamente.",
  "Shared company library. Upload, folder organisation and revision archive/restore are independent permissions. None grants procedure publication, private folders or permanent deletion.": "Biblioteca compartilhada da empresa. Enviar arquivos, organizar pastas e arquivar ou restaurar revisões são permissões independentes. Nenhuma delas autoriza publicar procedimentos, acessar pastas privadas ou excluir arquivos definitivamente.",
  "Separate schedule changes from assigning people. These actions apply to the person’s active departments unless the all-departments extension is explicitly enabled. A department-head title alone does not grant them. My shift and private handovers stay personal.": "Editar escalas e alocar pessoas são permissões separadas. Elas valem nos departamentos ativos da pessoa, salvo quando o acesso a todos os departamentos for concedido. Ser responsável por um departamento não concede essas permissões automaticamente. Meu turno e os rascunhos privados de passagem de turno continuam pessoais.",
  "Grant only the reusable-definition builders needed. These permissions do not grant user administration.": "Conceda apenas os editores de modelos necessários ao trabalho. Essas permissões não permitem administrar usuários.",
  "Issue QR links and admit temporary visitors separately. Document ownership, current revision and signing rules still apply.": "Emitir convites por código QR e permitir visitantes temporários são permissões separadas. As regras de autoria, versão do documento e assinatura continuam valendo.",
  "I separately reviewed the sensitive full-database backup grant.": "Revisei separadamente a permissão para baixar o banco de dados completo, que pode conter informações sensíveis.",
  "Existing saved flags are retained unless explicitly changed. The operational preset does not add backup, access delegation, all-departments shift scope or company-wide HR management/review rights. New shift permissions default off for non-admin accounts until granted.": "As permissões salvas são mantidas até serem alteradas. A opção de acesso operacional não inclui backup, delegação de acesso, escalas de todos os departamentos nem gestão e análise de RH da empresa. Para contas sem função de administrador, novas permissões de escala começam desmarcadas.",
  "Vessel-only account flags remain unchanged. Use Fleet access and separate logbook grants.": "As permissões desta conta restrita à embarcação são mantidas. Use o acesso à Frota e as permissões específicas dos livros de registro.",
  "Save or cancel the administration form before leaving this workspace.": "Salve ou cancele o formulário de administração antes de sair desta área.",
  "Save or cancel the administration form before changing workspace.": "Salve ou cancele o formulário de administração antes de mudar de área.",
