  "Local wording is not included in saved results. An uncertain submission needs review before a different save.": "O rascunho local não faz parte dos resultados salvos. Se o envio ficou sem confirmação, confira o registro antes de salvar novamente.",
  "These forms remain on this device. An attempted save may have succeeded despite a lost response; review Connection & saves and the saved record before changing or resubmitting. Permissions and saved versions are checked again.": "Estes formulários ficam neste dispositivo. Se a resposta foi interrompida, o servidor pode ter salvado o envio. Consulte Conexão e salvamentos e o registro antes de alterar ou reenviar. As permissões e versões serão conferidas novamente.",
