  "Current assignments and attention items only. Every title and deep link is re-derived through current source access; dismissed/read receipts contain no record text.": "A lista mostra atribuições e pendências que sua conta pode acessar agora. As permissões são conferidas novamente ao abrir cada registro. Marcar como lido ou dispensar não altera o registro de origem.",
