  "Retained from this draft; not currently eligible. Remove deliberately or ask an administrator.": "Mantido neste rascunho, mas sem acesso elegível no momento. Revise a seleção ou consulte o administrador.",
  "No eligible assignees available.": "Nenhuma pessoa com acesso para executar esta tarefa.",
  "No people match this search. Selected people outside the results stay selected.": "Nenhuma pessoa corresponde à busca. Pessoas já selecionadas fora dos resultados continuam selecionadas.",
  "Private to selected assignees, designated heads of this responsible department and company administrators. Department members are not automatically assigned.": "Acesso restrito aos responsáveis selecionados, chefias autorizadas do departamento e administradores. Os demais integrantes do departamento não são atribuídos automaticamente.",
  "Use its current saved version": "Usar a versão atual do registro",
  "A link does not grant access to its source or copy its readings, approvals or files. The saved version is checked again when creating the task.": "O vínculo não concede acesso ao registro de origem nem copia resultados, aprovações ou arquivos. A versão é conferida novamente ao criar a tarefa.",
  "Contribution points are frozen when this task is created. They recognise eligible documented contributors only after reviewed completion; they do not affect priority, approval or authority.": "Os pontos são definidos ao criar a tarefa e reconhecem contribuições registradas após a conclusão revisada. Não alteram prioridade, aprovação ou autoridade.",
  "Create assigns work; it does not complete maintenance, renew a certificate, verify stock or authorise equipment use.": "Criar a tarefa atribui trabalho. Não encerra manutenção, renova certificado, confere estoque nem autoriza o uso de equipamento.",
  "Inventory verification instead": "Precisa conferir itens do inventário?",
  "Use the separate fixed-scope inventory check workflow. Keep this draft before switching.": "Use a conferência de inventário para definir os itens e registrar os resultados da contagem. Guarde este rascunho antes de mudar.",
  "Keep draft & open inventory verification": "Guardar rascunho e abrir conferência de inventário",
  "Who will verify it": "Quem fará a conferência?",
  "Scope preview": "Itens incluídos na conferência",
