  "Selected boxes only — not the contents": "Somente as caixas selecionadas, sem o conteúdo",
  "Find scoped items": "Pesquisar nos itens da conferência",
  "Item, box, serial, PN or location": "Item, caixa, número de série, código da peça ou localização",
  "Select all shown": "Selecionar todos os itens exibidos",
