  "Verify each scoped record and record what you actually find.": "Confira cada item da lista e registre o que encontrou fisicamente, incluindo faltas e divergências.",
  "Send for review": "Enviar para análise",
  "All remaining items need a current result before submission.": "Registre um resultado atual para cada item pendente antes de enviar para revisão.",
  "Review the recorded outcomes before submitting.": "Confira os resultados registrados antes de enviá-los para revisão.",
  "People & due date": "Responsáveis e prazo",
  "Cancel unfinished task": "Cancelar tarefa não concluída",
  "Find a scoped item": "Pesquisar item desta conferência",
  "Search includes saved results.": "A busca inclui os resultados salvos.",
  "Selected result filter narrows this search.": "O filtro de resultado selecionado limita esta busca.",
  "Search and viewing do not record a check.": "Pesquisar ou abrir um item não registra uma conferência.",
  "Record every scoped item before submitting.": "Registre o resultado de todos os itens antes de enviar.",
  "Counted quantity; blank when unknown": "Quantidade contada; deixe em branco se não souber",
  "Notes (explain missing items or discrepancies)": "Observações (explique faltas ou divergências)",
  "Reason for replacing another person’s, submitted or moved result *": "Justificativa para substituir resultado de outra pessoa, já enviado ou com movimentação *",
