  "Submission note (optional)": "Observação para a revisão (opcional)",
  "Explanation for changing people or lowering priority": "Justificativa para alterar responsáveis ou reduzir a prioridade",
  "Changed assignees affect private access; reduced priority changes the follow-up. Explain the change.": "Alterar responsáveis muda quem acessa a tarefa; reduzir a prioridade muda seu acompanhamento. Justifique a alteração.",
  "Date-only updates and unchanged / increased priority need no generic reason. Your account and changes are recorded automatically.": "Alterações apenas de prazo ou aumento de prioridade não exigem justificativa. Sua conta e as alterações são registradas automaticamente.",
  "The account or view changed. Preserve this draft.": "A conta ou a tela mudou. Preserve este rascunho.",
  "Choose at least one active scoped item.": "Selecione pelo menos um item ativo para a conferência.",
