  "The account or verification view changed. Open the saved result again.": "A conta ou a conferência aberta mudou. Abra novamente o resultado salvo.",
  "The current item response did not match this verification. Refresh it before correcting a result.": "A resposta do item não corresponde a esta conferência. Atualize-a antes de corrigir o resultado.",
  "Back to verification": "Voltar à conferência de inventário",
  "Viewing this result does not record another check or change stock.": "Consultar este resultado não registra outra conferência nem altera o estoque.",
