  "This earlier result is no longer current. Review the latest item and record a new result before it counts toward completion.": "O resultado anterior está desatualizado. Confira a versão atual do item e registre um novo resultado para concluir a conferência.",
  "This saved result covers the box record. Its contents require separate results.": "Este resultado se refere à caixa. Cada item do conteúdo precisa de um resultado próprio.",
