  "Some earlier save outcomes are uncertain. They may already be on the hub. Their receipts stay; signing out cannot cancel those requests.": "Alguns salvamentos anteriores estão sem confirmação e podem já ter sido recebidos pelo servidor. Os comprovantes ficam guardados; sair da conta não cancela essas solicitações.",
