  "your account on this browser": "sua conta neste navegador",
  ". Discarding never deletes saved company records.": ". Descartar não exclui registros salvos da empresa.",
  "Scope, protected work & recovery": "Abrangência, trabalho protegido e recuperação",
  "In-tab-only forms and separate log windows are not included. Keep or close the current form first. Other accounts, saved signatures, published files and save receipts stay untouched. Unsettled saves remain protected. A recovery export can contain other accounts’ retained workspace data; keep it secure. It is not a full company backup.": "Formulários guardados somente na aba e janelas separadas de registros não estão incluídos. Guarde ou feche o formulário atual primeiro. Outras contas, assinaturas salvas, arquivos publicados e comprovantes de salvamento são preservados. Salvamentos sem confirmação ficam protegidos. A cópia de recuperação pode conter dados locais guardados de outras contas; mantenha-a protegida. Ela não é um backup completo da empresa.",
  "Separate log windows": "Janelas separadas de registros",
  "Select all eligible ({0})": "Selecionar os que podem ser descartados ({0})",
  "A save was attempted. Discarding this local copy does not undo any hub save.": "Houve uma tentativa de salvamento. Descartar esta cópia local não desfaz um salvamento no servidor.",
