  "Sort shipments": "Ordenar remessas",
  "Saved order": "Ordem registrada",
  "Manifest number A–Z": "Número do manifesto A–Z",
  "Planned arrival (earliest)": "Chegada prevista mais próxima",
  "‹ Back to shipments": "‹ Voltar para remessas",
  "Not planned": "Não planejado",
  "Selection cleared: that shipment is not in these results. No saved record changed.": "Seleção removida: a remessa não está nestes resultados. Nenhum registro salvo foi alterado.",
  "An earlier route filter is no longer available in this accessible shipment list. It has been cleared.": "Um filtro de rota anterior deixou de estar disponível nesta lista e foi removido.",
