  "Needs source review describes original extracted rows under the last applied mapping. It highlights possible headers, totals, instructions or document details; it does not remove or exclude rows. Later field edits do not reclassify this original-source advice.": "“Conferir no original” sinaliza possíveis cabeçalhos, totais, instruções ou dados do documento nas linhas extraídas, conforme a última correspondência de colunas aplicada. Nenhuma linha é removida ou excluída por esse aviso. Alterar os campos depois não reclassifica a linha original.",
