  "This is the currently chosen header. Inspect its source; no mapped-item jump is offered for a chosen header.": "Este é o cabeçalho escolhido atualmente. Consulte a linha original; cabeçalhos não oferecem acesso a um item importado.",
  "A unique positive original Excel coordinate could not be matched to a current nonmanual mapped row. No mapped item is inferred.": "Não foi possível relacionar uma linha original única do Excel a uma linha atual que não tenha sido editada manualmente. Nenhuma correspondência com item foi presumida.",
