  ". They remain Unknown; the literal source values are retained in Notes.": ". Elas continuam desconhecidas; os valores originais são preservados nas observações.",
  "Prior counted or actual quantities remain Source evidence in Notes, including zero and blank values. They do not verify this inventory.": "Quantidades contadas anteriormente permanecem nas observações como evidência do original, incluindo valores zero e campos vazios. Elas não confirmam o estoque deste inventário.",
  " prior quantity observations contain nonnumeric text. Expressions stay as written; nothing is calculated.": " contagens anteriores contêm texto não numérico. As expressões são preservadas como escritas; nenhum cálculo é realizado.",
