  "Part number uses “": "O número de peça usa “",
  "”. PN stays separate from the asset reference and serial number.": "”. PN permanece separado da identificação do equipamento e do número de série.",
  "No explicit box flag is mapped. BOX text in an asset reference does not create a container. Repeated item names stay separate.": "Nenhuma coluna indica explicitamente que o item é uma caixa. A palavra BOX na identificação não cria uma caixa. Itens com nomes repetidos continuam separados.",
  "These headings do not say whether they identify a box or its parent: ": "Estes cabeçalhos não indicam se identificam a própria caixa ou a caixa que a contém: ",
  ". Review the source and deliberately map them to Asset / tag reference or Parent box reference as appropriate. Unmapped values remain in Source Notes; no relationship is inferred.": ". Confira o original e associe-os à identificação do equipamento ou à referência da caixa principal, conforme o caso. Valores sem correspondência permanecem nas observações do original; nenhum vínculo é presumido.",
  " source rows were skipped because their item name is an omitted formula. Supply literal names in the source before importing those rows.": " linhas foram ignoradas porque o nome do item é uma fórmula omitida. Substitua a fórmula por um nome confirmado no original antes de importar essas linhas.",
  " nonempty source rows have no item name at ": " linhas preenchidas do original estão sem nome de item em ",
  ". They are excluded. Add a confirmed item name in the source or mapped rows if these are inventory items.": ". Elas não serão incluídas. Se representam itens de inventário, informe um nome confirmado no original ou nas linhas preparadas.",
  " mapped formula cells were omitted. Their values remain blank or unknown; omission evidence stays in Source Notes for retained rows. No formula was calculated.": " células com fórmulas foram omitidas. Seus valores continuam vazios ou desconhecidos; a indicação da omissão fica nas observações das linhas mantidas. Nenhuma fórmula foi calculada.",
  "Selected file and worksheet references are retained as Source evidence in Notes. Source departments, dates and verification labels do not assign a department, record custody or verify Wavelink stock.": "As referências ao arquivo e às abas selecionadas ficam nas observações. Departamentos, datas e rótulos de conferência presentes no original não atribuem departamento, registram custódia nem confirmam o estoque no Wavelink.",
