  "Enter an item name up to 1,200 characters and optional serial and part numbers up to 500 characters. Use single-line text.": "Informe o nome do item com até 1.200 caracteres. Número de série e número de peça são opcionais, com até 500 caracteres cada. Use uma única linha por campo.",
  "Item names, serials and part numbers were edited. Item choices and existing source evidence are kept. Applying the mapping again replaces these edits with mapped source values.": "Os nomes, números de série e números de peça foram editados. A seleção de itens e a evidência do original foram mantidas. Reaplicar a correspondência substitui essas edições pelos valores das colunas do original.",
  "Choose items · ": "Selecionar itens · ",
  "The mapped rows need all 13 inventory columns. Apply the mapping or correct the full mapped rows before editing boxes and contents.": "As linhas preparadas precisam conter as 13 colunas do inventário. Aplique a correspondência de colunas ou corrija as linhas completas antes de editar caixas e conteúdos.",
  "Choose Yes or No for Is box. The source flag was not recognized.": "Escolha Sim ou Não no campo “É caixa”. O indicador do original não foi reconhecido.",
  "A box row must represent one container: use expected quantity 1 or leave it Unknown.": "Uma linha de caixa deve representar um único recipiente: informe quantidade prevista 1 ou mantenha a quantidade desconhecida.",
  "This box has no asset reference. Other rows cannot refer to it.": "Esta caixa não tem identificação. Outras linhas não podem se referir a ela.",
