  "Mapping changed. Original row matches could not be confirmed; all mapped rows are included again. Choose items before checking.": "A correspondência mudou. Não foi possível confirmar os vínculos com as linhas originais; todas as linhas preparadas foram incluídas novamente. Selecione os itens antes de conferir.",
