  "Full mapped rows were edited. Boxes and contents now use that edited text; earlier field edits are replaced. Original Excel row references are unavailable until you apply mapping again.": "As linhas completas foram editadas. Caixas e conteúdos agora usam esse texto, substituindo as edições anteriores dos campos. As referências ao Excel ficam indisponíveis até reaplicar a correspondência de colunas.",
  "Mapped rows were edited. Item choices reset: all mapped rows are included. Original Excel row references are unavailable until you apply mapping again.": "As linhas preparadas foram editadas. A seleção foi redefinida: todas as linhas estão incluídas. As referências ao Excel ficam indisponíveis até reaplicar a correspondência de colunas.",
