  "Choose an Excel (XLSX, XLSM, XLSB, XLS, XLTX or XLTM), PDF, DOCX, PNG or JPEG original. Macro-enabled Word files are not supported.": "Escolha um original Excel (XLSX, XLSM, XLSB, XLS, XLTX ou XLTM), PDF, DOCX, PNG ou JPEG. Documentos do Word com macros não são aceitos.",
  "Choose an original file between 1 byte and {0} MB.": "Escolha um arquivo com tamanho entre 1 byte e {0} MB.",
  "Link up to 12 original document revisions to one checklist.": "Cada vínculo pode conter até 12 revisões do original.",
  "This original document is not in the current project. Restore a complete backup or import the source again and relink the draft.": "Este original não está no projeto atual. Restaure uma cópia de segurança completa ou importe o original novamente e refaça o vínculo no rascunho.",
  "Original files exceed the setup-transfer budget. Use a full project transfer, or export a smaller linked checklist library.": "Os arquivos originais ultrapassam o limite desta transferência de configurações. Use a transferência completa do projeto ou exporte um acervo menor de listas vinculadas.",
