  "Mapping reapplied. All mapped rows are included. {0}": "Correspondência de colunas reaplicada. Todas as linhas mapeadas estão incluídas. {0}",
  "All items use reviewed location: {0}": "Todos os itens usam o local conferido: {0}",
  "{0} source row{1} already in this inventory.": "Linhas do original já presentes neste inventário: {0}.",
  "Original row references are missing or could not be confirmed for {0} worksheet{1}.": "Abas sem referências confirmadas às linhas do original: {0}.",
  " · {0} Unknown expected quantit{1}": " · quantidades esperadas não informadas: {0}",
  "{0} worksheets shown · {1}. Needs mapping includes excluded worksheets; excluded pending choices do not block checking the selected proposal.": "Abas exibidas: {0} · {1}. A indicação de correspondência pendente inclui abas excluídas; pendências nas abas excluídas não impedem conferir a proposta selecionada.",
  "{0}. Map and confirm its item rows before including it as inventory.": "{0}. Associe as colunas e confirme as linhas de itens antes de incluí-la como inventário.",
  "Column {0} · {1}": "Coluna {0} · {1}",
