  "{0} rows mapped from {1}.{2}": "{0} linhas mapeadas de {1}.{2}",
  "Apply mapping to worksheet “{0}”? This replaces your {1} with mapped source values. Item choices are retained only when original rows can be confirmed. Cancel keeps this worksheet draft and its review.": "Aplicar a correspondência de colunas à aba “{0}”? Isso substitui {1} pelos valores mapeados do original. A seleção dos itens só é mantida quando as linhas originais podem ser confirmadas. Cancelar mantém o rascunho e sua conferência.",
  "{0} source prompt{1} added to your current discussion. Review the wording, then check the edited draft again.": "Tópicos do original adicionados à discussão atual: {0}. Confira a redação e depois confira novamente o rascunho editado.",
