  "Your {0} unsent entries and any new-record draft remain with the previous workspace. Nothing will be submitted here automatically.": "Seus {0} registros ainda não enviados e os rascunhos de novos registros permanecem na área anterior. Nada será enviado automaticamente para esta empresa.",
  "Switching stores the previous company workspace separately on this browser and requires sign-in. To resume its queued work, reopen that company service and switch back here. Do not clear site data. This is not a merge between company workspaces.": "A troca mantém a área da empresa anterior salva separadamente neste navegador e exige novo login. Para retomar os envios pendentes, abra novamente o serviço daquela empresa e volte para a área correspondente. Não apague os dados do site. Os dados das empresas não serão mesclados.",
