  "Invitation email is not configured": "O envio de convites por e-mail não está configurado",
  "Your server operator must enable invite-only enrollment and configure TLS-protected transactional email. Existing named accounts and sign-in are unchanged. No invitation will be created or claimed sent while email is disabled.": "O responsável pelo serviço precisa habilitar o cadastro por convite e configurar o envio seguro de e-mails. As contas existentes continuam funcionando. Nenhum convite será criado ou informado como enviado enquanto o envio de e-mails estiver desabilitado.",
  "Email is configured. Submission to the mail server is not confirmation that an invitation reached the inbox.": "O envio de e-mails está configurado. A aceitação pelo servidor de e-mail não confirma a entrega na caixa de entrada.",
  "Department, displayed job role and explicit permissions are stored separately. Record privacy, assignment, custody and designated-approver rules still apply.": "Lotação, função exibida e permissões são configurações separadas. Continuam valendo as regras de privacidade, atribuição, custódia e aprovação de cada registro.",
