  "Last saved access view — refresh failed. Actions are paused until refreshed.": "Última consulta de acesso salva. Não foi possível atualizar; as ações ficam indisponíveis até a atualização.",
  "Your account has no company-access delegation. An administrator can configure the actions and departments you may manage.": "Sua conta não tem delegação para gerenciar acessos. Um administrador pode configurar as ações e os departamentos sob sua responsabilidade.",
  "Access decision saved.": "Decisão de acesso salva.",
  "Save reviewed access": "Salvar permissões conferidas",
  "This form stays in this tab until saved. Closing does not save it. Access changes are attributed to your named account.": "Este formulário permanece nesta aba até ser salvo. Fechá-lo não salva as alterações. A decisão de acesso fica registrada em seu nome.",
  "Wait for this access request to finish.": "Aguarde a conclusão desta solicitação de acesso.",
