  "Adjust access": "Ajustar permissões",
  "This can only narrow the selected role. Uncheck access deliberately; permissions outside the role cannot be added here.": "Aqui você pode apenas reduzir os acessos do perfil selecionado. Desmarque o que não for necessário; novas permissões não podem ser acrescentadas por este formulário.",
  "Management and administrator invitations use the complete reviewed profile. Edit the company role profile before sending if its authority is wrong.": "Convites de gestão e administração usam o perfil completo. Se as permissões não estiverem corretas, edite o perfil da empresa antes de enviar.",
  "No active role profile is available within your invitation authority.": "Não há perfil de acesso ativo que você tenha autorização para convidar.",
  "Choose job role": "Escolher perfil de acesso",
  "Choose a job role": "Escolha um perfil de acesso",
  "Select a role to review its exact permissions and whether it can activate after mailbox verification.": "Selecione um perfil para conferir suas permissões e saber se o acesso será ativado após verificar o e-mail.",
  "Choose the exact mailbox, department and displayed job role. No company record is exposed before that mailbox is verified.": "Informe o e-mail correto, a lotação e o perfil de acesso. Nenhum registro da empresa fica disponível antes da verificação do e-mail.",
  "Recipient email": "E-mail de quem receberá o convite",
  "The link expires after seven days. A valid pre-authorised invitation activates only its signed snapshot; otherwise the verified person remains pending with no operational access.": "O link expira em sete dias. Um convite previamente autorizado ativa apenas as permissões aprovadas no momento da emissão. Nos demais casos, a pessoa fica aguardando análise, sem acesso às operações.",
  "Choose an available role profile.": "Escolha um perfil de acesso disponível.",
  "Keep at least one operational permission, or cancel this role-ready invitation.": "Mantenha pelo menos uma permissão operacional ou cancele o convite.",
  "Invitation submitted. After exact mailbox verification, the signed role and access can activate without a second review.": "Convite enviado ao serviço de e-mail. Após verificar o endereço informado, as permissões previamente autorizadas poderão ser ativadas sem nova análise.",
  "Invitation submitted. The verified person will remain pending until an authorised access review.": "Convite enviado ao serviço de e-mail. Após verificar o endereço, a pessoa aguardará a análise de um responsável autorizado.",
  "Resend invitation": "Reenviar convite",
  "Revoke invitation": "Revogar convite",
  "approved after verification": "autorizado após verificar o e-mail",
  "approval required": "exige aprovação",
  "This rotates the link while retaining the same validated role/access snapshot. If authority or the profile changed, a new reviewed invitation is required.": "O link será substituído, mantendo o perfil e as permissões já conferidos. Se a autorização ou o perfil mudou, será necessário emitir um novo convite após análise.",
  "This stops new acceptance. It does not delete an existing member or erase the invitation history.": "Impede o uso deste convite. A conta de um membro já cadastrado e o histórico do convite são preservados.",
  "The email outcome is unconfirmed. Check this invitation before retrying.": "O resultado do envio do e-mail não foi confirmado. Confira este convite antes de tentar novamente.",
  "Replacement invitation submitted with the same reviewed snapshot.": "Novo link enviado ao serviço de e-mail, com as mesmas permissões conferidas.",
  "Invitation revoked.": "Convite revogado.",
  "Send replacement link": "Enviar novo link",
  "No role-ready invitation snapshot is attached. This is a legacy or locally created account.": "Esta conta foi criada localmente ou antes dos convites com perfil de acesso. Não há proposta de permissões vinculada ao convite.",
  "Review access request": "Analisar solicitação de acesso",
