  "Operational permissions": "Permissões operacionais",
  "The proposed role access is selected where it is inside your authority. Review every item. Nothing outside that signed participant proposal may be added during this approval.": "As permissões propostas aparecem selecionadas quando estão dentro da sua autoridade. Confira cada item. Esta aprovação não permite acrescentar permissões fora da proposta registrada no convite.",
  "Your approval authority does not include granting operational permissions.": "Sua autorização de aprovação não inclui conceder permissões operacionais.",
  "Membership decision saved. The person can refresh their own status.": "Decisão de acesso salva. A pessoa pode atualizar a consulta de sua situação.",
  "Save access decision": "Salvar decisão de acesso",
