  "active grant": "permissão vigente",
  "withdrawn": "retirada",
  "No delegated grants.": "Nenhuma permissão delegada.",
  "Operational grants are disabled until this member returns to review.": "A concessão de permissões operacionais ficará indisponível até este membro voltar para análise.",
  "Grant selected permissions": "Conceder permissões selecionadas",
  "Withdraw from selected source": "Retirar da origem selecionada",
  "Source for withdrawal": "Origem das permissões a retirar",
  "Only selected rights change. Independent administrator and other coordinators’ rights are preserved. Having access is not enough to delegate it: every permission must also be inside your approved allowance.": "Somente as permissões selecionadas serão alteradas. As permissões diretas do administrador e as concedidas por outros responsáveis serão preservadas. Para delegar um acesso, é necessário ter autorização específica para concedê-lo.",
  "Suspend membership": "Suspender acesso do membro",
