  "Return this membership to review first.": "Primeiro retorne este membro para análise.",
  "Selected access updated. Existing operational sessions were revoked; the person must sign in again.": "Permissões selecionadas atualizadas. As sessões anteriores foram encerradas; a pessoa precisará entrar novamente.",
  "Discard this unsaved access proposal and review the membership state instead?": "Descartar esta proposta ainda não salva e analisar a situação do membro?",
  "This removes operational access while preserving the person’s identity and recorded work. Returning to pending requires a new explicit approval and permission grant.": "Retira o acesso operacional e preserva a conta e o trabalho registrado. O retorno para análise exige nova aprovação e concessão de permissões.",
  "Membership state changed.": "Situação do acesso atualizada.",
  "Suspend access": "Suspender acesso",
  "Return to review": "Retornar para análise",
  "Configure access delegation": "Configurar delegação de acesso",
