  "Allowed responsibilities": "Responsabilidades autorizadas",
  "Departments they may manage": "Departamentos sob sua responsabilidade",
  "Permissions they may grant": "Permissões que poderá conceder",
  "Add this person to the intended department in People & access first.": "Primeiro vincule esta pessoa ao departamento desejado em Pessoas e acesso.",
  "Only independently held permissions are offered. No self-promotion, administrator changes, onward delegation, backup export or all-department shift scope. Saving a changed delegation stops this person’s previous delegated grants until deliberately re-authorised; independent administrator grants remain.": "Apenas permissões próprias, recebidas de forma independente, podem ser delegadas. Não é permitido ampliar o próprio acesso, alterar administradores, repassar delegações, exportar backups ou gerenciar turnos de todos os departamentos. Ao alterar a delegação, as concessões anteriores desta pessoa ficam suspensas até nova autorização. As permissões diretas do administrador são mantidas.",
  "Delegation saved. The coordinator must sign in again. Previously issued delegated grants require review.": "Delegação salva. O responsável precisará entrar novamente. As permissões que ele já havia delegado precisam de revisão.",
  "Administrator authority is complete and explicit. Only an existing administrator can issue this role.": "O perfil de administrador concede administração completa. Somente um administrador atual pode emitir este convite.",
  "Choose the explicit operational capabilities. Dependencies are selected together. A role name never grants authority by itself.": "Selecione as permissões operacionais. As permissões necessárias para cada ação são selecionadas em conjunto. O nome do perfil, sozinho, não concede acesso.",
  "Participant access this role may delegate": "Acessos de colaboradores que este perfil poderá delegar",
  "This remains bounded by the coordinator’s department scope and current independently held access.": "A delegação fica limitada aos departamentos e às permissões próprias do responsável.",
  "Administrator invitation authority remains complete; backup export and all-department shift authority are never delegated onward.": "O administrador mantém a autorização para convidar. A exportação de backups e a gestão de turnos de todos os departamentos não podem ser repassadas por delegação.",
  "No role template is available.": "Nenhum modelo de perfil de acesso está disponível.",
  "Create a versioned company job-role profile.": "Crie um perfil de acesso da empresa com controle de versões.",
  "Saving creates a new immutable revision; existing invitations and members keep their recorded snapshot.": "Salvar cria uma nova versão. Os convites emitidos e os membros existentes mantêm as permissões registradas anteriormente.",
