  "Review transport details & notes": "Conferir transporte e observações",
  "Save creates a Draft, not a dispatch. The hub checks complete active box contents and current access. Inspect the saved scope and attachments before separately marking Ready.": "Salvar cria um rascunho. O sistema confere o conteúdo das caixas e seu acesso atual. Confira os itens e anexos salvos antes de marcar a remessa como pronta.",
  "Review this shipment": "Conferir esta remessa",
  "Check the route and complete box contents, then deliberately mark the manifest ready.": "Confira a rota e todo o conteúdo das caixas antes de marcar o manifesto como pronto.",
  "Readiness review note *": "Parecer da conferência para despacho *",
  "Confirm Ready": "Confirmar como pronta",
  "Confirm Ready — not dispatch": "Confirmar como pronta para despacho",
  "Confirm readiness": "Confirmar prontidão do dispositivo",
  "Ready does not mean in transit. Confirm dispatch only when the equipment actually leaves.": "Uma remessa pronta ainda não está em trânsito. Confirme o despacho somente quando os equipamentos saírem fisicamente.",
  "I reviewed the route, item identities, recorded quantities and full included box contents.": "Conferi a rota, os identificadores dos itens, as quantidades registradas e todo o conteúdo das caixas.",
  "Confirm physical dispatch": "Confirmar saída física",
  "Record the physical departure of every saved shipment group. The same equipment records become In transit.": "Registre a saída física de todos os grupos da remessa. Os mesmos equipamentos passarão para a situação Em trânsito.",
  "Do not use a planned departure as proof that the equipment has left. The server rechecks custody, item versions and full box contents.": "A data prevista não comprova a saída dos equipamentos. O sistema confere novamente a custódia, as versões dos itens e o conteúdo completo das caixas.",
  "Dispatch note / physical event *": "Observação sobre a saída física *",
  "I checked this shipment and am recording its actual departure.": "Conferi a remessa e estou registrando sua saída física.",
  "Cancel undispatched manifest": "Cancelar manifesto ainda não despachado",
  "Retain this undispatched manifest as Cancelled. No physical receipt, return or inventory movement is recorded.": "Mantém o manifesto como Cancelado. Não registra recebimento, devolução física nem movimentação de inventário.",
  "Only Draft or Ready shipments can be cancelled. Dispatched equipment needs a recorded receipt or return instead.": "Somente remessas em rascunho ou prontas podem ser canceladas. Para equipamentos já despachados, registre o recebimento ou a devolução.",
  "This shipment has not dispatched and is no longer going ahead.": "Esta remessa não foi despachada e não será realizada.",
  "Cancelled before dispatch": "Cancelada antes do despacho",
