  "Review and close the shipment": "Conferir e encerrar a remessa",
  "Close the shipment record after every group has been received or returned and finally placed.": "Encerre a remessa após receber ou devolver todos os grupos e registrar sua localização final.",
  "Closing does not release quarantine, verify equipment or complete maintenance. Holding equipment must be placed first.": "O encerramento não libera quarentena, não confere equipamentos nem conclui manutenção. Registre primeiro o destino dos equipamentos em recebimento provisório.",
