  "Vessel logbook setup": "Configuração dos livros da embarcação",
  "Link reviewed logbooks to a vessel, then grant separate site-specific log permissions.": "Vincule os livros conferidos a uma embarcação e configure as permissões de registro específicas desse local.",
  "Vessel log permissions": "Permissões dos registros da embarcação",
