  "Review the pending follow-up": "Analisar próxima ordem pendente",
  "View the retained results": "Consultar resultados preservados",
  "The completed evidence remains saved. A manager must review the changed requirements before creating a next order.": "As evidências concluídas estão preservadas. Um gestor precisa analisar os requisitos alterados antes de gerar a próxima ordem.",
  "This order is locked. Its saved evidence and history remain available.": "A edição desta ordem está bloqueada. As evidências e o histórico continuam disponíveis.",
  "No named assignees — maintenance workers": "Sem responsáveis específicos — equipe com permissão de manutenção",
  "No additional work-order instructions.": "Sem instruções adicionais para esta ordem.",
  "Review saved steps ({0})": "Conferir etapas salvas ({0})",
  "{0} · {1} · Approval: {2}": "{0} · {1} · Aprovação: {2}",
  "{0} saved steps and {1} required approvals still need attention. Completion must pass the existing server checks; cancellation retains this unfinished work without marking it done.": "Etapas pendentes: {0}. Aprovações pendentes: {1}. A conclusão depende das conferências do servidor. Cancelar preserva o trabalho pendente sem marcá-lo como concluído.",
  "{0} local maintenance form(s) exist for this order. They are not included in these saved totals. Review saved forms before deciding whether the work is complete.": "Há {0} formulário(s) local(is) de manutenção desta ordem. Eles não estão incluídos nos totais salvos. Confira os formulários antes de concluir o trabalho.",
  "Use no more than {0} characters.": "Use no máximo {0} caracteres.",
