  "{0} previous assignee(s) are not offered by the current directory and will not be retained. Review the available people before saving.": "Há {0} responsável(is) anterior(es) indisponível(is) no cadastro atual. Eles não serão mantidos. Confira as pessoas disponíveis antes de salvar.",
