  "This corrects approved work or another person’s saved result, so a short explanation is required. Changed results need any required approval again.": "Esta alteração corrige um resultado aprovado ou registrado por outra pessoa. Informe uma justificativa. O resultado alterado precisará das aprovações exigidas novamente.",
