  "Review the photo list before saving.": "Confira a lista de fotos antes de salvar.",
  "New work order for this item": "Nova ordem de serviço para este equipamento",
  "New maintenance work order": "Nova ordem de serviço",
  "Choose a published routine, name the work and create one open order.": "Selecione uma rotina publicada, identifique o trabalho e crie a ordem de serviço.",
