  "No linked asset.": "Nenhum equipamento vinculado.",
  "No linked task.": "Nenhuma tarefa vinculada.",
  "Private to the reporter, current assigned owner, current designated heads of the selected active department and project administrators with HSE / QSHE access. Avoid unnecessary personal, medical or identifying details. This is not anonymous or restricted-to-the-HSE-team reporting. Links require their own source access.": "Acesso restrito ao relator, ao responsável atual, aos responsáveis designados pelo departamento ativo selecionado e aos administradores com acesso a Segurança e qualidade. Evite dados pessoais, médicos ou identificadores desnecessários. O relato não é anônimo nem fica restrito à equipe de segurança. Cada vínculo exige acesso à sua origem.",
  "This is a retained HSE / QSHE report, not an emergency channel, permit to work, risk assessment approval, medical record or regulatory notification. Follow your company emergency, escalation and reporting procedures separately. Closing this report does not release equipment, remove quarantine, authorise operation, complete a linked Task, change stock, complete maintenance or renew a certificate.": "Este relato de segurança e qualidade mantém um histórico. Utilize os procedimentos próprios da empresa para emergências, acionamento de responsáveis e comunicações obrigatórias. Este relato não substitui permissão de trabalho, aprovação de análise de risco, prontuário médico ou notificação a órgãos reguladores. Encerrá-lo não libera equipamentos ou quarentena, não autoriza operações, não conclui tarefas ou manutenção, não altera estoque e não renova certificados.",
  "Same person proposed and reviewed closure. This is not independent review.": "A mesma pessoa propôs e revisou o encerramento. Não houve revisão independente.",
  "The selected owner gains report access. A former owner may lose access unless they are also its reporter or an authorised manager. This does not reassign a linked Task.": "O responsável selecionado terá acesso ao relato. O responsável anterior poderá perder esse acesso, salvo se também for relator ou gestor autorizado. Esta alteração não muda o responsável por uma tarefa vinculada.",
  "Eligible people: {0} · search keeps the selected owner": "Pessoas elegíveis: {0} · a busca preserva o responsável selecionado",
  "Selected owner: ": "Responsável selecionado: ",
  "Waiting for hub confirmation…": "Aguardando confirmação do servidor…",
  "Required for a nonconformity or audit finding. Preserve any recorded requirement when changing report type.": "Obrigatório para não conformidades ou constatações de auditoria. Preserve o requisito já registrado ao mudar o tipo de relato.",
  "Choose one exact accessible record. Linking does not complete it or give other people access to it.": "Selecione o registro exato ao qual você tem acesso. Vinculá-lo não o conclui nem concede acesso a outras pessoas.",
