  "Previously entered change note (optional)": "Justificativa anterior (opcional)",
  "This changes recorded source information or the record state. Explain that correction; normal working notes, responsibility and reminder updates need no reason.": "Esta alteração modifica dados da fonte ou a situação do registro. Justifique a correção. Atualizações de acompanhamento, responsabilidade e avisos não exigem justificativa.",
  "Your earlier note is retained. You may keep, edit or clear it.": "A justificativa anterior foi preservada. Você pode mantê-la, editá-la ou apagá-la.",
  "Use the expiry stated on the source. Its full UTC calendar date counts; no dates are calculated for you.": "Use o vencimento informado na fonte. A data é considerada até o fim do dia em UTC; o sistema não calcula datas de validade.",
  "A date is still entered. Choose a recorded expiry, or explicitly clear that date before saving.": "Há uma data preenchida. Selecione vencimento informado ou apague essa data antes de salvar.",
  "Use this only when the source explicitly declares no expiry. It does not mean equipment is approved.": "Use somente quando a fonte declarar expressamente validade indeterminada. Isso não significa aprovação do equipamento.",
  "Unknown expiry remains unknown. No date or no-expiry declaration is inferred.": "Vencimento não informado permanece desconhecido. O sistema não presume uma data nem validade indeterminada.",
  "Review retained assignment": "Conferir responsável preservado",
