  "Review this field.": "Confira este campo.",
  "Record the supplied certificate. Save once; attach the original file on the saved record.": "Cadastre as informações do certificado recebido. Depois de salvar, anexe o arquivo original ao registro.",
  "Your name, time and before/after changes are recorded automatically. This registers supplied information; it does not authenticate a certificate, approve equipment or replace an issued source.": "Seu nome, o horário e as alterações são registrados automaticamente. O cadastro organiza as informações fornecidas; não autentica o certificado, não aprova equipamentos nem substitui o documento emitido.",
