  "Select a reviewed Task or explicitly choose Remove optional link before saving.": "Selecione uma tarefa conferida ou escolha Remover vínculo opcional antes de salvar.",
  "Review the change and tick the confirmation.": "Confira a alteração e marque a confirmação.",
  "Private to the reporter, current assigned owner, current designated heads of the selected active department and project administrators with Fault Reports access. Written notes are shared with that audience; source links require separate access.": "Acesso restrito ao relator, ao responsável designado, aos gestores atuais do departamento e aos administradores com acesso aos relatórios de falha. As observações são compartilhadas com esse grupo; os registros vinculados exigem acesso próprio.",
  "This record tracks a reported fault and its reviewed corrective work. It does not release equipment, remove quarantine, authorise operation, change stock, complete maintenance, renew a certificate or complete a linked Task. Follow the responsible organisation’s safety and equipment-release procedures separately.": "Este registro acompanha uma falha relatada e a revisão do trabalho corretivo. Não libera equipamentos, remove quarentena, autoriza operações, altera estoque, conclui manutenção, renova certificados nem conclui tarefas vinculadas. Siga também os procedimentos de segurança e liberação de equipamentos da organização responsável.",
