  "Blank custom logbook": "Livro personalizado em branco",
  "Online hub connection required. This unsaved design exists only in this tab. Event time, author identity, notes and correction history are automatic; units are labels, not measurement conversions or operating limits.": "É necessário estar conectado ao servidor. Esta estrutura ainda não salva fica somente nesta aba. Data do evento, autoria, observações e histórico de correções são registrados pelo sistema. As unidades apenas identificam os valores; não fazem conversões nem definem limites operacionais.",
  "Give this logbook a clear name": "Dê um nome claro ao livro de registro",
  "Purpose / instructions": "Finalidade e instruções",
  "EXACT STRUCTURE REVIEWED BY THE HUB": "ESTRUTURA CONFERIDA PELO SERVIDOR",
  "Create saves one empty company logbook. Saved structures are fixed; this does not alter existing books, copy vessel grants or approve operations.": "A criação salva um livro vazio da empresa. A estrutura salva não pode ser alterada por este editor. A ação não modifica outros livros, copia permissões de embarcação nem aprova operações.",
