  "Replace the unsaved section structure with this starting point? The name and purpose stay.": "Substituir as seções ainda não salvas por esta estrutura inicial? O nome e a finalidade serão mantidos.",
  "The hub did not return a complete structure review. Nothing was created.": "O servidor não retornou uma conferência completa da estrutura. Nenhum livro foi criado.",
  " No logbook was created by this review.": " Nenhum livro foi criado por esta conferência.",
  "Add at least one field": "Adicione pelo menos um campo",
