  "Edit selected field": "Editar o campo selecionado",
  "Required for every entry in this section": "Obrigatório em todos os registros desta seção",
  "Dropdown choices — one per line": "Opções da lista — uma por linha",
  "Units are descriptive only. Changing the label or order keeps this unsaved field's identity.": "As unidades são apenas descritivas. Mudar o nome ou a ordem mantém a identidade deste campo ainda não salvo.",
  "Technical identifier": "Identificador técnico",
  "The logbook builder account or editor changed. No request was sent.": "A conta ou o editor de livros mudou. Nenhuma solicitação foi enviada.",
  "Unexpected response. Check saved Logs before creating another book.": "Resposta inesperada. Confira os livros salvos em Registros operacionais antes de criar outro.",
  "HUB CONFIRMED / EMPTY LOGBOOK CREATED": "CONFIRMADO PELO SERVIDOR / LIVRO VAZIO CRIADO",
  "Your new logbook is saved. Existing logbooks and their evidence were not changed.": "O novo livro de registro foi salvo. Os livros existentes e suas evidências foram preservados.",
  " The logbook may already exist. Retry this unchanged request, or close and check saved Logs before another creation.": " O livro pode já ter sido criado. Tente novamente com a mesma solicitação ou feche e confira os registros salvos antes de criar outro.",
  " Review the current design again before creating it.": " Confira novamente a estrutura atual antes de criá-la.",
  "Close this uncertain design? It may already be saved. Check Logs and the retained request receipt before creating another. The design text is not in the receipt.": "Fechar esta estrutura sem confirmação do resultado? Ela pode já estar salva. Confira os livros e o comprovante da solicitação antes de criar outro. O texto da estrutura não faz parte do comprovante.",
  "Discard this unsaved design? No logbook is created by cancelling.": "Descartar esta estrutura ainda não salva? O cancelamento não cria um livro de registro.",
