  "Required when saved information changes. An unchanged save needs no explanation.": "Obrigatória quando as informações salvas são alteradas. Salvar sem alterações não exige justificativa.",
  "Discard local draft": "Descartar rascunho local",
  "No unsent log drafts for this account and company workspace.": "Não há rascunhos de registros não enviados para esta conta e empresa.",
  "Your local draft is retained. A revision conflict requires comparing the latest entry; do not overwrite it blindly.": "Seu rascunho local foi mantido. Em caso de conflito de versões, compare com o registro mais recente antes de salvar.",
  "This marks the entry void. It does not erase its evidence or audit history.": "Esta ação anula o registro. As evidências e o histórico de auditoria são preservados.",
