  "(not a live assignment)": "(não representa uma atribuição atual)",
  "Original source contact:": "Contato informado na fonte:",
  "An in-app alert is sent after this entry is saved. Assignment does not grant edit access; no email or push message is sent.": "Após salvar, um aviso será criado no aplicativo. A atribuição não concede permissão de edição nem envia e-mail ou notificação externa.",
  "Colours identify the recorded event or status; they do not control equipment or certify work. Unconfirmed source times remain labelled and are excluded by UTC date filters. Imported source names are not account signatures. New entries use the signed-in user.": "As cores identificam eventos ou situações; não controlam equipamentos nem certificam o trabalho. Horários de fonte não confirmados são identificados e ficam fora dos filtros por data UTC. Nomes importados não são assinaturas de contas. Novos registros usam a conta conectada.",
  "On a laptop, scroll inside the log table. Filters open above the table without making it smaller. Close filters when finished. Use Home, Checklists or All logbooks to leave this view.": "Role dentro da tabela para consultar todas as colunas. Os filtros ficam acima dela e podem ser fechados ao terminar. Use Início, Listas de verificação ou Todos os livros para mudar de área.",
  "Assignment is not permission to correct the event. Current assignees with log-entry permission can update only response/status. Resolved means reported resolved, not independent approval or equipment release.": "A atribuição não concede permissão para corrigir o evento. Responsáveis com acesso aos registros podem atualizar apenas a resposta e a situação. Resolvido significa resolução informada, sem aprovação independente nem liberação de equipamentos.",
  "These forms remain on this device. An attempted save may have succeeded despite a lost response; check Connection & saves and the saved record before changing or resubmitting. A company backup does not contain device-only drafts.": "Estes formulários permanecem neste dispositivo. Um salvamento pode ter sido concluído mesmo sem resposta; confira Conexão e salvamentos e o registro antes de alterar ou reenviar. O backup da empresa não inclui rascunhos que existem apenas no dispositivo.",
  "Export the current log as a table: same columns, newest-first order and event colours. Uses all matching hub-saved entries, not just the visible page.": "Exporte o livro atual em tabela, com as mesmas colunas, ordem dos mais recentes e identificação dos eventos. A exportação inclui todos os registros salvos que correspondem aos filtros, além da página visível.",
  "Current search, UTC date and Show voided filters are applied. Reference pictures, unsent drafts and the full correction history are not included.": "São aplicados os filtros de busca, data UTC e registros anulados. Imagens de referência, rascunhos não enviados e o histórico completo de correções não são incluídos.",
  "Excel scope": "Abrangência da planilha",
  "All log sections — one sheet per section": "Todas as seções — uma aba por seção",
  "PDF: landscape table with repeated headings; wide All columns reports use numbered column groups. Limit: 1,000 entries. CSV is plain text without colours.": "PDF: tabela em paisagem com cabeçalhos repetidos; relatórios largos agrupam as colunas em partes numeradas. Limite de 1.000 registros. O CSV contém texto, sem cores.",
  "CSV table": "Tabela CSV",
