  "Both daily choices use the reason-free notes form. People & shifts manages recurring assignments. For irregular periods use More actions → Manual / irregular daily period.": "As duas opções diárias abrem o formulário de observações, sem exigir justificativa. Gerencie a escala recorrente em Escalas e alocação de pessoas. Para períodos irregulares, use Mais ações → Período diário manual ou irregular.",
