  "No active department is available to this account. Ask your lead to check department membership. Full-hitch and existing records remain available.": "Sua conta não está vinculada a um departamento ativo. Solicite ao responsável a conferência da lotação. Você ainda pode criar uma passagem de período completo ou consultar registros existentes.",
