  "Acknowledgements, configured reviews and membership requests within your approval scope. General administrator access does not make every operational review yours.": "Confirmações de leitura, revisões e solicitações de acesso dentro da sua responsabilidade. O acesso de administrador não atribui automaticamente todas as revisões a você.",
