  "The account, session, route or checklist stage changed. Close this review and reopen the intended record. No new action was sent by this control.": "A conta, a sessão ou a etapa mudou. Feche esta conferência e reabra o registro desejado. Nenhuma nova ação foi enviada.",
  "The request is in progress. Check the save-status strip for its outcome.": "A solicitação está em andamento. Consulte Conexão e salvamentos para acompanhar o resultado.",
  "This review note has not been saved or queued. Close and discard this unsent note?": "Este parecer ainda não foi salvo nem colocado na fila de envio. Deseja fechar e descartar o texto não enviado?",
  "Local work is waiting. Preserve it, save drafts, synchronise and resolve conflicts before reviewing this action again.": "Há trabalho local pendente. Preserve os dados, salve os rascunhos, envie as alterações e resolva as divergências antes de conferir novamente.",
  "The saved stage or known device state changed during review. Refresh saved review and confirm the latest information.": "A etapa salva ou a situação do dispositivo mudou durante a conferência. Atualize a consulta e confira os dados atuais.",
