  "Only the designated person or an enabled assigned-group member may decide. Administrator access is not an override.": "Somente a pessoa designada ou um membro habilitado do grupo responsável pode decidir. O acesso de administrador não substitui essa atribuição.",
  "This account is not permitted to perform this action.": "Esta conta não tem permissão para executar esta ação.",
