  "A named checker must review and save this result before approval.": "Uma pessoa identificada precisa conferir e salvar o resultado antes da aprovação.",
  "Save a Completed or Not applicable result before its approval review.": "Salve o resultado como Concluído ou Não se aplica antes de conferir sua aprovação.",
  "This device is not joined to this stage. Refresh while connected.": "Este dispositivo não está participando da etapa. Atualize a página com conexão ao servidor.",
  "The hub reports unsynchronised work on this device. Synchronise before readiness.": "O servidor indica alterações não sincronizadas neste dispositivo. Envie-as antes de marcá-lo como pronto.",
