  "Ready": "Pronto",
  "Unfinished exports are labelled In progress. Disconnected phones may still hold unsent work.": "Relatórios de etapas ainda não concluídas são identificados como Em andamento. Dispositivos sem conexão podem manter alterações ainda não enviadas.",
  "Check number, wording, readings or note": "Número, texto, medição ou observação da verificação",
  "The upload outcome is unconfirmed. Closing loses the selected file and retry state. Record the upload reference and check the saved library before another upload. Close anyway?": "O resultado do envio não foi confirmado. Fechar descarta a seleção do arquivo e os dados para repetir a mesma tentativa. Anote a referência do envio e confira a biblioteca antes de enviar novamente. Deseja fechar?",
  "This upload is not saved or queued. Close and discard the selected file and unsaved form?": "Este envio não foi salvo nem colocado na fila. Deseja fechar e descartar a seleção do arquivo e os dados não salvos?",
  "Original files (Library root)": "Arquivos originais (pasta raiz)",
  "No destination selected": "Nenhum destino selecionado",
  "The earlier folder is no longer available. Choose a destination again.": "A pasta anterior não está mais disponível. Escolha novamente uma pasta de destino.",
  "Choose a supported PDF, DOCX, PNG/JPEG or Excel original.": "Escolha um arquivo original em PDF, DOCX, PNG, JPEG ou Excel.",
  "Browser uploads support one file from 1 byte to 20 MB, including Excel. Larger Excel originals retain the native-admin import workflow.": "Envie um arquivo de 1 byte a 20 MB, inclusive Excel. Arquivos Excel maiores devem seguir o procedimento de importação administrativa existente.",
  "File verification needs HTTPS or localhost. Use the established secure Wavelink address; this form does not weaken browser security.": "A conferência do arquivo exige HTTPS ou ambiente local. Use o endereço seguro do Wavelink. Este formulário mantém as proteções do navegador.",
