  "One complete original file will be shared with permitted company-workspace readers. Nothing is published, approved or silently replaced.": "O arquivo original completo ficará disponível às pessoas autorizadas nesta empresa. Este envio não publica nem aprova procedimentos e não substitui arquivos existentes.",
  "Adding a revision of": "Nova revisão de",
