  "Original bytes, including hidden workbook content/macros, are retained. Format checks are not malware scanning. Adding a revision does not redirect existing source links.": "O conteúdo original é preservado, inclusive partes ocultas e macros de planilhas. A conferência do formato não faz varredura de vírus. Uma nova revisão não altera os vínculos existentes com a fonte.",
  "Upload outcome unconfirmed. Keep this selected file and use the same request to retry. Closing cannot undo an upload already sent.": "Resultado do envio ainda não confirmado. Mantenha este arquivo selecionado e repita a mesma solicitação. Fechar não desfaz um envio já recebido pelo servidor.",
