  "Use Move location / Put in box / Take out for existing equipment movements. Moving an existing box with contents is a separate, reviewed action. This editor cannot dispatch, receive or release equipment.": "Para movimentar equipamentos existentes, use Mover local, Colocar em caixa ou Retirar da caixa. A movimentação de uma caixa com conteúdo exige conferência própria. Este cadastro não registra despacho, recebimento nem liberação de equipamentos.",
