  "Fill the form with your reviewed wording. Hub draft saving and publication are separate. Incomplete forms cannot be saved.": "Preencha e confira o formulário. Salvar o rascunho no servidor não o publica. Complete os campos para salvar.",
  "Published forms have no parallel hub draft. This proposal stays only in the open tab until complete review and explicit publication.": "A proposta de revisão fica nesta aba até ser conferida e publicada. O formulário já publicado permanece disponível.",
  "Online, in-memory authoring only. Closing/reloading can lose unsaved wording. Request receipts contain identifiers and status, not the complete form. Keep uncertain requests open for unchanged retry.": "O editor precisa de conexão. Salve antes de fechar ou atualizar a página para preservar os textos. Se o resultado do envio estiver incerto, mantenha o editor aberto para conferir e tentar novamente sem alterar a solicitação.",
