  "Saved form wording": "Conteúdo salvo do formulário",
  "Retained source and imported definition (read-only)": "Fonte e definição importada preservadas — somente leitura",
  "Read-only form: pending source review or unsupported definition fields must be reviewed in native Admin. The browser will not discard them or approve the source.": "Formulário somente para consulta: a conferência da fonte ou dos campos não compatíveis deve ser feita na administração do aplicativo instalado. Esses dados são preservados e a fonte não é aprovada pelo navegador.",
  "Archived for future selection. Existing briefings and their evidence remain unchanged.": "Arquivado para novos usos. Os diálogos e as evidências existentes são preservados.",
  "I reviewed this exact form change. Publication is not a personal acknowledgement, permit or approval to operate.": "Conferi esta alteração do formulário. A publicação não representa ciência dos participantes nem autorização para executar a atividade.",
  "Save this complete unpublished draft to the hub first; then review the saved form separately for publication.": "Salve o formulário completo como rascunho no servidor. Depois confira a versão salva e confirme a publicação.",
  "Hub review matches this complete wording and the loaded saved revision. Confirm below to publish; no operational acknowledgement will be made.": "A conferência corresponde a este conteúdo e à versão salva. Confirme abaixo para publicar. A publicação não registra ciência dos participantes.",
  "Reordering affects the next form revision, not answers in existing talks.": "A ordem será usada na próxima versão do formulário. As respostas dos diálogos existentes serão preservadas.",
  "Add a blank entry, then provide reviewed wording.": "Adicione um item e preencha o texto que será usado no diálogo.",
  "Checking this complete wording against the current saved form…": "Conferindo este conteúdo com a versão salva do formulário…",
  "Invalid form review response. No publication was sent.": "Não foi possível confirmar o resultado da conferência. A publicação não foi enviada.",
  "Wording is unchanged. Confirming will not create an extra revision.": "O conteúdo não mudou. A confirmação não criará outra versão.",
  "Review complete. Nothing has been published; confirm separately below.": "Conferência concluída. O formulário ainda não foi publicado; confirme abaixo.",
  " The earlier save remains uncertain. A later failed request does not prove it failed; inspect the saved form before any different submission.": " O resultado do envio anterior ainda é incerto. Confira a versão salva antes de enviar uma alteração diferente.",
  " These proposed fields are read-only. Preserve needed wording, close and reload the saved form.": " Os campos desta proposta estão disponíveis apenas para consulta. Preserve os textos necessários, feche e abra novamente a versão salva.",
  " No publication was sent.": " Nenhuma publicação foi enviada.",
