  "Optional manual guest list for the existing witnessed acknowledgement. Temporary QR visitors can instead enter their own details on the signing page; do not pre-add them as well.": "Lista opcional para registrar ciência com testemunha. Quem entrar pelo código QR pode informar os próprios dados; evite cadastrar a mesma pessoa nas duas formas.",
  "Add named guest": "Adicionar participante sem conta",
  "Full name *": "Nome completo",
  "Company — optional": "Empresa — opcional",
  "Guest note — optional": "Observação sobre o participante — opcional",
  "Briefing notes — optional": "Observações do diálogo — opcional",
  "What participants acknowledge": "Declaração de ciência dos participantes",
  "Save briefing": "Salvar diálogo",
  "The value is frozen when the briefing is created. Each eligible named account can receive it once after valid personal acknowledgement and finalisation. Guests are not merged into member points.": "A pontuação é definida na criação do diálogo. Cada conta habilitada pode recebê-la uma vez após confirmar ciência e concluir o diálogo. Participantes sem conta não recebem esses pontos.",
  "Save briefing records these notes only. It does not sign for anyone, open a QR, finalise the talk or authorise work. Changes invalidate earlier QR invitations.": "Salvar registra o diálogo, sem assinar por participantes, abrir código QR, concluir o registro ou autorizar a atividade. Alterações invalidam os convites QR anteriores.",
  "Record each answer from the discussion. No is a request to revisit the question, not a reason to hide the answer.": "Registre cada resposta dada no diálogo. Uma resposta Não indica que o assunto precisa ser retomado e deve permanecer registrada.",
  "Retained reference — not currently eligible. Remove deliberately or ask an administrator.": "Participante preservado do registro anterior, atualmente sem habilitação. Revise sua permanência ou consulte a administração.",
  "Retained attendee": "Participante preservado",
  "This talk has already been shared/signed, is another author's record, or lacks a complete local history. Explain a correction; saving changed wording or people resets current acknowledgements. Earlier evidence stays in History.": "Este diálogo já foi compartilhado ou assinado, pertence a outra pessoa ou não tem histórico local completo. Justifique a correção. Alterar o conteúdo ou os participantes exige novas confirmações de ciência; as anteriores permanecem no histórico.",
  "Correction explanation — required for changes": "Justificativa da correção — obrigatória para alterar",
  "Retained change note": "Justificativa anterior preservada",
  "Previously entered note — optional": "Observação anterior — opcional",
  "Enter the site, work description and UTC briefing time.": "Informe o local, a descrição da atividade e a data e hora do diálogo em UTC.",
  "Enter each listed guest’s name or remove the empty guest.": "Informe o nome de cada participante sem conta ou remova o cadastro vazio.",
  "Use at most 150 participants including named guests.": "O limite é de 150 participantes, incluindo pessoas sem conta.",
  "Use at most 150 participants.": "O limite é de 150 participantes.",
  "Mark every topic as actually discussed? Understanding answers and signatures are not changed.": "Confirmar que todos os tópicos foram discutidos? As respostas de compreensão e as assinaturas serão preservadas.",
  "Remove this saved guest from the draft roster? Saving changed people requires new acknowledgements.": "Remover esta pessoa da lista do rascunho? Salvar a alteração de participantes exige novas confirmações de ciência.",
  "Guest draft needs recovery. Preserve this draft rather than clearing it.": "A lista de participantes precisa ser recuperada. Preserve este rascunho.",
  "The saved guest list is invalid. Preserve this draft and its recovery copy.": "A lista salva de participantes não pôde ser validada. Preserve este rascunho e a cópia de recuperação.",
  "Keep or close the open form before choosing another briefing.": "Mantenha o rascunho ou feche o formulário antes de escolher outro diálogo.",
  "Keep or close the open form before opening another briefing.": "Mantenha o rascunho ou feche o formulário antes de abrir outro diálogo.",
  "Sign in to the original company workspace and account before resuming this form.": "Entre na empresa e na conta de origem para retomar este formulário.",
  "You need Toolbox Talks conduct permission to record a briefing.": "É necessário ter permissão para conduzir diálogos de segurança.",
  "This briefing is no longer open for editing. Reload the saved record.": "Este diálogo não está mais aberto para edição. Atualize o registro salvo.",
  "Only the talk owner or an administrator may edit this briefing.": "Somente o responsável pelo diálogo ou a administração pode editá-lo.",
  "The selected form changed or is unavailable. Choose its current published revision before starting a new talk.": "O formulário mudou ou está indisponível. Escolha a versão publicada atual antes de iniciar um diálogo.",
