  "Low stock (": "Estoque baixo (",
  "Documents up to 12 MB become editable proposals. Review the type, worksheet and extracted wording before saving. Older DOC/XLS files need to be saved as DOCX/XLSX first.": "Documentos de até 12 MB geram uma proposta que você pode editar. Confira o tipo, a aba da planilha e o texto extraído antes de salvar. Converta arquivos antigos DOC/XLS para DOCX/XLSX antes de importar.",
  "About logbook packages (.ajlogs)": "Sobre arquivos de livros de registros (.ajlogs)",
  "Logbook packages up to 150 MB can provide their form design. Saved entries, offsets, reference pages and pictures stay out of the new logbook.": "Arquivos de livros de registros de até 150 MB podem fornecer a estrutura do formulário. Registros salvos, valores de ajuste, páginas de referência e imagens não são copiados para o novo livro.",
  "Loading the current saved step…": "Carregando a etapa salva…",
