  "Review the changed shift setup before creating it.": "Confira a configuração alterada do turno antes de criá-lo.",
  "Review complete. Nothing has been created. Read the proposed draft, give a reason and confirm separately.": "Conferência concluída. Nada foi criado. Leia a proposta de rascunho, informe a justificativa e confirme em seguida.",
  "Close setup and continue my saved draft": "Fechar configuração e continuar meu rascunho salvo",
  "Review the shift setup, give a reason and confirm it first.": "Confira a configuração do turno, informe a justificativa e confirme antes de continuar.",
  "Waiting for the hub to confirm your private shift draft…": "Aguardando o servidor confirmar seu rascunho privado de turno…",
  "{0} named person(s) and {1} department(s) selected. Filtering does not remove selections.": "Pessoas selecionadas: {0}. Departamentos selecionados: {1}. Os filtros não removem essas seleções.",
  "Check the date and shift hours: {0}": "Confira a data e os horários dos turnos: {0}",
  "A full 24-hour cycle is required.": "O ciclo de turnos deve cobrir 24 horas.",
  "People & shifts assigns department members to recurring shifts. The choices below apply only to your own new handover.": "Pessoas e turnos define a escala recorrente dos integrantes do departamento. As opções abaixo se aplicam somente à sua nova passagem de turno.",
  "Choose the shift covered by your own handover below. The corresponding Shifts & people permission is required to change recurring staff assignments.": "Escolha abaixo o turno da sua passagem. Para alterar a escala recorrente da equipe, é necessária a permissão correspondente em Pessoas e turnos.",
  "Repeated identifiers across worksheets · {0} groups": "Identificadores repetidos entre abas · {0} grupos",
  "This comparison only checks different worksheets. Repeated identifiers within the same worksheet are not counted here; inspect its selected rows separately.": "Esta comparação considera apenas abas diferentes. Identificadores repetidos dentro da mesma aba não entram nesta contagem; confira suas linhas selecionadas separadamente.",
  "No exact cross-worksheet SN or asset matches were found in the compared rows. This does not rule out repeated identifiers within one worksheet or items recorded with missing or different identifiers.": "Não foram encontradas correspondências exatas de número de série ou referência de ativo entre as abas comparadas. Ainda pode haver identificadores repetidos na mesma aba ou itens registrados sem identificador ou com identificadores diferentes.",
  "Same company workspace and saved data": "Mesma área de trabalho e mesmos dados da empresa",
  "Already open as an app": "O aplicativo já está aberto como app instalado",
  "Your browser is offering installation": "Seu navegador permite instalar o aplicativo",
  "App / home-screen options": "Opções de instalação e da tela inicial",
  "Home-screen shortcut at this HTTP address": "Atalho na tela inicial para este endereço HTTP",
  "Use one Wavelink window at a time in each browser. Installing does not create a separate hub.": "Use uma janela principal do Wavelink por vez em cada navegador. A instalação não cria outro servidor da empresa.",
  "Select Install app below to open the browser’s installation prompt.": "Selecione Instalar aplicativo abaixo para abrir a confirmação de instalação do navegador.",
  "No native install prompt is available right now. Check the browser menu; availability depends on the browser and device policy.": "O navegador não oferece a confirmação de instalação neste momento. Confira seu menu; a disponibilidade depende do navegador e das regras do dispositivo.",
  "The app menu is working, but this address is not a secure browser context. You may add a browser shortcut to your home screen. Full web-app installation and offline reopening need trusted HTTPS.": "O menu do aplicativo está funcionando, mas este endereço não é uma conexão segura para o navegador. Você pode adicionar um atalho à tela inicial. A instalação completa e a reabertura offline exigem uma conexão HTTPS confiável.",
  "Secure browser context detected.": "Conexão segura reconhecida pelo navegador.",
  "No secure browser context detected.": "O navegador não reconheceu uma conexão segura.",
  "The company service is still required for sharing and syncing records.": "O servidor da empresa continua necessário para compartilhar e sincronizar registros.",
  "Android · Chrome or Edge": "Android · Chrome ou Edge",
  "Windows laptop · Edge or Chrome": "Computador Windows · Edge ou Chrome",
  "Open the": "Abra o",
