  ", not Wavelink’s ☰ menu. Look for": ", fora do menu ☰ do Wavelink. Procure",
  "Add to Home screen": "Adicionar à tela inicial",
  ". On HTTP, the browser may offer only": ". Em um endereço HTTP, o navegador pode oferecer apenas",
