  ", then": ", depois em",
  "when offered. On HTTP, treat it as an online shortcut; do not assume offline reopening works.": "quando disponível. Em HTTP, trate a opção como um atalho que precisa de conexão; não presuma que funcione offline.",
  "Use the browser’s": "Use a opção",
  "Apps / Install": "Aplicativos / Instalar",
  "or shortcut option when offered. The Windows": "ou a criação de atalho do navegador, quando disponível. No Windows, o arquivo",
  "installs the PC hub and Admin console; it does not install a phone application.": "instala o servidor local e a administração no computador; ele não instala um aplicativo no celular.",
  "Keep saved work safe": "Preserve o trabalho salvo",
  "Installing a shortcut is not a fix for a storage restriction. Do not clear site data with unsent work. Sync/export before changing HTTP to HTTPS, changing the IP address or port, or switching browser. Those addresses/windows may have separate local storage.": "Instalar um atalho não resolve restrições de armazenamento. Não limpe os dados do site enquanto houver trabalho não enviado. Sincronize ou exporte antes de trocar HTTP por HTTPS, mudar o endereço IP ou a porta, ou usar outro navegador. Cada endereço ou navegador pode ter armazenamento local separado.",
  "Full installation, HTTPS and offline use": "Instalação completa, HTTPS e uso offline",
  "The hub must use a certificate trusted by the phone. See": "O servidor deve usar um certificado aceito pelo celular. Consulte",
  "Admin → Settings": "Administração → Configurações",
  "and the": "e o",
  "secure connections guide": "guia de conexões seguras",
  ". Ask your administrator for the approved secure address. Load the secure app while connected, then test reopening offline before relying on it. The company service is still required for sharing and syncing records.": ". Solicite ao administrador o endereço seguro aprovado. Abra o aplicativo seguro com conexão e teste a reabertura offline antes de depender dela. O servidor da empresa continua necessário para compartilhar e sincronizar registros.",
  "Current origin": "Endereço atual",
  "Do not replace the hub address with localhost on a phone.": "No celular, não substitua o endereço da empresa por localhost.",
  "Print QR labels…": "Imprimir etiquetas QR…",
  "Open QR / asset ID": "Abrir código QR ou ID do ativo",
  "Export CSV · all records": "Exportar CSV · todos os registros",
  "Choose all stock, an area/department, a box or just selected rows. This creates labels only; it never verifies or moves items.": "Escolha todos os itens do inventário, uma área ou departamento, uma caixa ou apenas as linhas selecionadas. Esta ação gera somente etiquetas; não confere nem movimenta itens.",
  "Selected rows ({0})": "Linhas selecionadas ({0})",
  "{0} label(s) · {1} page(s)": "Etiquetas: {0} · Páginas: {1}",
  "Preview included items": "Conferir itens incluídos",
  "Archived items are excluded. All means all active records in this inventory—not only visible rows. Review the count, print at actual size and test one label. The label needs the saved company-workspace address.": "Itens arquivados ficam de fora. A opção de selecionar todos abrange todos os registros ativos deste inventário, inclusive os que não estão visíveis. Confira a quantidade, imprima em tamanho real e teste uma etiqueta. A etiqueta usa o endereço da empresa configurado no sistema.",
  "Save outcome uncertain: the hub may have saved this action before the response was lost. Check the saved record before sending a different action. Only an unchanged retry with the same operation ID can be recognised as that request.": "Resultado do salvamento incerto: o servidor pode ter salvo esta ação antes de a resposta se perder. Confira o registro salvo antes de enviar uma ação diferente. Somente uma nova tentativa idêntica, com o mesmo identificador de operação, pode ser reconhecida como a mesma solicitação.",
  "The hub response was received, but the page could not finish updating. Review Connection & saves and the saved record before repeating the action.": "A resposta do servidor foi recebida, mas a página não conseguiu concluir a atualização. Consulte Conexão e salvamentos e o registro salvo antes de repetir a ação.",
  "The hub could not be reached or its response could not be read. Fleet forms are not an offline queue; keep this page open and preserve unsaved values.": "Não foi possível acessar o servidor ou ler a resposta. Os formulários da frota não funcionam como uma fila de envio sem conexão; mantenha esta página aberta e preserve os valores ainda não salvos.",
  "The hub could not be reached or its response could not be read. Only work explicitly confirmed as saved on this device is retained.": "Não foi possível acessar o servidor ou ler a resposta. Somente o trabalho com confirmação explícita de salvamento neste dispositivo fica preservado.",
