  "Acceptance confirms responsibility for this assignment. It is separate from reading an alert, starting work and approving completion.": "O aceite confirma sua responsabilidade por esta atribuição. É diferente de ler um alerta, iniciar a execução ou aprovar a conclusão.",
  "Each assigned person records their own acceptance. Earlier acceptances remain in task history after reassignment or reopening.": "Cada responsável registra o próprio aceite. Após uma reatribuição ou reabertura, os aceites anteriores permanecem no histórico da tarefa.",
  "Review the instructions and assigned people before accepting. This does not record work performed or grant access to linked records.": "Confira as instruções e os responsáveis antes de aceitar. O aceite não registra a execução do trabalho nem concede acesso aos registros vinculados.",
  "I reviewed this assignment and accept my responsibility for it.": "Conferi esta atribuição e aceito minha responsabilidade por ela.",
  "This acceptance is recorded for your own account, with the date and time.": "O aceite será registrado na sua conta, com data e hora.",
  "Retry will check the original request. It will not accept a newer assignment automatically.": "A nova tentativa verificará o pedido original. Uma atribuição mais recente não será aceita automaticamente.",
